define(['ko','uiComponent'],function(ko,Component){'use strict';return Component.extend({defaults:{vendorName:'Amasty',templates:{closeButton:'Amasty_Base/submenu/components/close_button',link:'Amasty_Base/submenu/components/link',title:'Amasty_Base/submenu/components/title',submenuSecond:'Amasty_Base/submenu/second_level',menu_lists:'Amasty_Base/submenu/menu_lists',links_list:'Amasty_Base/submenu/links_list',item_label:'Amasty_Base/submenu/components/item_label',},elemIndex:0,exports:{solutions:'ambase_solutions:data',simples:'ambase_simples:data',links:'ambase_links:data'}},initObservable:function(){return this._super().observe({secondLevelItem:false,isDropdownActive:false,noSearchResults:false,simples:[],solutions:[],links:[]});},afterRender:function(){var simples=[],solutions=[],links=[];this.data.forEach(function(item){if(item.type==='simple'){simples.push(item);}else if(item.type==='link'){links.push(item);}else{solutions.push(item);}}.bind(this));this.simples(simples);this.solutions(solutions);this.links(links);},setActiveItem:function(item){this.resetActiveItem();this.secondLevelItem(item);},resetActiveItem:function(){this.secondLevelItem(false);}});});